#!/usr/bin/env python3
"""Merge multiple JUnit XML report files into one summary.

Accepts files whose root is either ``<testsuites>`` wrapping several
``<testsuite>`` elements, or a bare ``<testsuite>`` root. Malformed XML
produces a per-file warning without aborting the merge of remaining files.
"""

import sys
import xml.etree.ElementTree as ET


def _iter_testsuites(path):
    """Yield <testsuite> Elements found in *path*.

    Raises ET.ParseError for unreadable/malformed XML.
    """
    tree = ET.parse(path)
    root = tree.getroot()
    if root.tag == "testsuites":
        suites = [e for e in root.iter("testsuite")]
        if not suites:
            # Degenerate wrapper with no children: treat root itself as empty.
            return
        yield from suites
    elif root.tag == "testsuite":
        yield root
    else:
        raise ValueError(f"unexpected root element {root.tag!r} in {path}")


def _to_float(value, default=0.0):
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def _collect_suite(suite, file_totals):
    """Accumulate one <testsuite> into file_totals; collect its testcases."""
    for attr in ("tests", "failures", "errors", "skipped"):
        try:
            file_totals[attr] += int(float(suite.get(attr, 0)))
        except ValueError:
            pass
    file_totals["time"] += _to_float(suite.get("time"))

    cases = []
    for case in suite.iter("testcase"):
        case_time = _to_float(case.get("time"))
        status = "passed"
        message = None
        for child in case:
            if child.tag in ("failure", "error", "skipped"):
                status = child.tag
                message = child.get("message") or (child.text or "").strip() or None
                break
        cases.append(
            {
                "name": case.get("name"),
                "classname": case.get("classname"),
                "time": case_time,
                "status": status,
                "message": message,
            }
        )
    return cases


def merge_reports(paths):
    """Merge JUnit XML files given by *paths*.

    Returns ``(summary, warnings)`` where *summary* is::

        {
            "per_file": {path: {"tests": .., "failures": .., "errors": ..,
                                "skipped": .., "time": float}},
            "total": {...same shape...},
            "slowest": [{"classname","name","time","file"}, ...],  # <= 5, slowest first
            "failures_markdown": "...",
        }

    and *warnings* is a list of strings describing skipped files.
    """
    all_cases = []
    per_file = {}
    warnings = []

    for path in paths:
        file_totals = {"tests": 0, "failures": 0, "errors": 0, "skipped": 0, "time": 0.0}
        try:
            for suite in _iter_testsuites(path):
                cases = _collect_suite(suite, file_totals)
                for case in cases:
                    entry = dict(case)
                    entry["file"] = path
                    all_cases.append(entry)
        except (ET.ParseError, OSError, ValueError) as exc:
            warnings.append(f"warning: skipping {path}: {exc}")
            continue
        per_file[path] = file_totals

    total = {
        key: sum(ft[key] for ft in per_file.values())
        for key in ("tests", "failures", "errors", "skipped", "time")
    }
    total["time"] = round(total["time"], 6)

    slowest = sorted(all_cases, key=lambda c: c["time"], reverse=True)[:5]

    lines = ["## Failures", ""]
    failing = [c for c in all_cases if c["status"] in ("failure", "error")]
    if not failing:
        lines.append("No failures or errors.")
    else:
        for case in failing:
            title = f"{case['classname']}.{case['name']}" if case["classname"] else str(case["name"])
            kind = "ERROR" if case["status"] == "error" else "FAIL"
            lines.append(f"- **[{kind}] `{title}`** ({case['file']})")
            if case["message"]:
                quoted = "\n".join(f"  > {line}" for line in case["message"].splitlines())
                lines.append(quoted.rstrip())
            lines.append("")

    summary = {
        "per_file": per_file,
        "total": total,
        "slowest": slowest,
        "failures_markdown": "\n".join(lines).rstrip() + "\n",
    }
    return summary, warnings


def format_report(summary):
    """Render the summary as human-readable Markdown."""
    total = summary["total"]
    out = [
        "# JUnit Merge Summary",
        "",
        "## Per-file totals",
        "",
        "| File | Tests | Failures | Errors | Skipped | Time (s) |",
        "|---|---|---|---|---|---|",
    ]
    for path, ft in summary["per_file"].items():
        out.append(
            f"| {path} | {ft['tests']} | {ft['failures']} | {ft['errors']}"
            f" | {ft['skipped']} | {ft['time']:.3f} |"
        )
    out += [
        f"| **Total** | **{total['tests']}** | **{total['failures']}**"
        f" | **{total['errors']}** | **{total['skipped']}** | **{total['time']:.3f}** |",
        "",
        "## 5 Slowest Test Cases",
        "",
    ]
    if not summary["slowest"]:
        out.append("No test cases found.")
    for i, case in enumerate(summary["slowest"], 1):
        name = f"{case['classname']}.{case['name']}" if case["classname"] else str(case["name"])
        out.append(f"{i}. `{name}` — {case['time']:.3f}s ({case['file']})")
    out += ["", summary["failures_markdown"].rstrip(), ""]
    return "\n".join(out)


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    if not argv:
        print("usage: junit_merge.py REPORT.xml [REPORT.xml ...]", file=sys.stderr)
        return 2
    summary, warnings = merge_reports(argv)
    for warning in warnings:
        print(warning, file=sys.stderr)
    print(format_report(summary))
    return 0


if __name__ == "__main__":
    sys.exit(main())

